import { HistoricalDocument } from '../../types';

export const codigoManuCapitulo3: HistoricalDocument = {
  id: 'codigo-manu-capitulo-3',
  title: 'Capítulo III',
  subtitle: 'Do Casamento e dos Deveres do Chefe de Família',
  date: 'c. 200 a.C. – 200 d.C.',
  era: 'Índia Antiga',
  language: 'Sânscrito',
  description: 'Trata das formas de casamento, dos deveres do chefe de família e dos ritos destinados aos manes.',
  parentCollectionId: 'codigo-de-manu',
  sections: [
    {
      id: 'versos',
      title: 'Capítulo III',
      type: 'articles',
      articles: [
        { id: 'cm-3-1', number: 'Verso 1', text: `O voto (de estudar) os três Vedas sob um professor deve ser mantido por trinta e seis anos, ou pela metade desse tempo, ou por um quarto, ou até que o (estudante) os tenha aprendido perfeitamente.` },
        { id: 'cm-3-2', number: 'Verso 2', text: `(Um estudante) que estudou na devida ordem os três Vedas, ou dois, ou mesmo apenas um, sem quebrar as (regras do) aprendizado, deverá entrar na ordem dos chefes de família.` },
        { id: 'cm-3-3', number: 'Verso 3', text: `Aquele que é famoso pela (estrita realização de) seus deveres e recebeu sua herança, o Veda, de seu pai, deverá ser honrado, sentado em um sofá e adornado com uma guirlanda, com (o presente de) uma vaca (e a mistura de mel).` },
        { id: 'cm-3-4', number: 'Verso 4', text: `Tendo se banhado, com a permissão de seu professor, e realizado de acordo com a regra o *Samavartana* (o rito ao retornar para casa), um homem duas-vezes-nascido deverá casar-se com uma esposa de casta igual que seja dotada de marcas (corporais) auspiciosas.` },
        { id: 'cm-3-5', number: 'Verso 5', text: `Uma donzela que não é nem uma *Sapinda* do lado da mãe, nem pertence à mesma família do lado do pai, é recomendada aos homens duas-vezes-nascidos para o matrimônio e união conjugal.` },
        { id: 'cm-3-6', number: 'Verso 6', text: `Ao ligar-se a uma esposa, que ele evite cuidadosamente as dez famílias seguintes, sejam elas por maiores que sejam, ou ricas em gado, cavalos, ovelhas, grãos, ou (outras) propriedades,` },
        { id: 'cm-3-7', number: 'Verso 7', text: `(A saber) uma que negligencie os ritos sagrados, uma na qual não (nascem) filhos do sexo masculino, uma na qual o Veda não é estudado, uma (cujos membros) têm pelos grossos no corpo, aquelas que estão sujeitas a hemorroidas, tísica, fraqueza de digestão, epilepsia, ou lepra branca ou negra.` },
        { id: 'cm-3-8', number: 'Verso 8', text: `Que ele não se case com uma donzela (com cabelos) avermelhados, nem com uma que tenha um membro redundante, nem com uma que seja doentia, nem com uma com nenhum pelo (no corpo) ou muito, nem com uma que seja tagarela ou tenha (olhos) vermelhos,` },
        { id: 'cm-3-9', number: 'Verso 9', text: `Nem com uma nomeada em homenagem a uma constelação, uma árvore, ou um rio, nem com uma que tenha o nome de uma casta baixa, ou de uma montanha, nem com uma nomeada em homenagem a um pássaro, uma cobra, ou um escravo, nem com uma cujo nome inspire terror.` },
        { id: 'cm-3-10', number: 'Verso 10', text: `Que ele despose uma fêmea livre de defeitos corporais, que tenha um nome agradável, o andar (gracioso) de um *Hamsa* ou de um elefante, uma (quantidade) moderada de pelos no corpo e na cabeça, dentes pequenos, e membros macios.` },
        { id: 'cm-3-11', number: 'Verso 11', text: `Mas um homem prudente não deve casar-se (com uma donzela) que não tenha irmão, nem com uma cujo pai não seja conhecido, por medo de que (no primeiro caso ela seja feita) uma filha designada (e no último) para que não (cometa) pecado.` },
        { id: 'cm-3-12', number: 'Verso 12', text: `Para o primeiro casamento de homens duas-vezes-nascidos são recomendadas (esposas) de casta igual; mas para aqueles que por desejo procedem (a casar-se novamente) as seguintes fêmeas, (escolhidas) de acordo com a ordem (direta) (das castas), são as mais aprovadas.` },
        { id: 'cm-3-13', number: 'Verso 13', text: `É declarado que apenas uma mulher *Sudra* (pode ser) a esposa de um *Sudra*, ela e uma de sua própria casta (as esposas) de um *Vaisya*, essas duas e uma de sua própria casta (as esposas) de um *Kshatriya*, essas três e uma de sua própria casta (as esposas) de um *Brahmana*.` },
        { id: 'cm-3-14', number: 'Verso 14', text: `Uma mulher *Sudra* não é mencionada sequer em nenhuma história (antiga) como a (primeira) esposa de um *Brahmana* ou de um *Kshatriya*, embora eles vivessem na (maior) aflição.` },
        { id: 'cm-3-15', number: 'Verso 15', text: `Homens duas-vezes-nascidos que, em sua loucura, desposam esposas da casta baixa (*Sudra*), logo degradam suas famílias e seus filhos ao estado de *Sudras*.` },
        { id: 'cm-3-16', number: 'Verso 16', text: `De acordo com Atri e com (Gautama) o filho de Utathya, aquele que desposa uma mulher *Sudra* torna-se um pária, de acordo com Saunaka no nascimento de um filho, e de acordo com Bhrigu aquele que tem descendência (masculina) (apenas de uma fêmea *Sudra*).` },
        { id: 'cm-3-17', number: 'Verso 17', text: `Um *Brahmana* que toma uma esposa *Sudra* em sua cama, (após a morte) afundará no inferno; se ele gerar um filho com ela, ele perderá a posição de um *Brahmana*.` },
        { id: 'cm-3-18', number: 'Verso 18', text: `Os manes e os deuses não comerão as (oferendas) daquele homem que realiza os ritos em honra aos deuses, aos manes, e aos convidados principalmente com a assistência (de uma esposa *Sudra*), e tal (homem) não irá para o céu.` },
        { id: 'cm-3-19', number: 'Verso 19', text: `Para aquele que bebe a umidade dos lábios de uma *Sudra*, que é maculado por sua respiração, e que gera um filho nela, nenhuma expiação é prescrita.` },
        { id: 'cm-3-20', number: 'Verso 20', text: `Agora ouvi (a) breve (descrição dos) oito ritos matrimoniais a seguir, usados pelas quatro castas (*varna*) que em parte garantem benefícios e em parte produzem o mal tanto nesta vida quanto após a morte.` },
        { id: 'cm-3-21', number: 'Verso 21', text: `(Eles são) o rito de Brahman (*Brahma*), o dos deuses (*Daiva*), o dos Rishis (*Arsha*), o de Pragapati (*Pragapatya*), o dos Asuras (*Asura*), o dos Gandharvas (*Gandharva*), o dos Rakshasas (*Rakshasa*), e o dos Pisakas (*Paisaka*).` },
        { id: 'cm-3-22', number: 'Verso 22', text: `Qual é lícito para cada casta (*varna*) e quais são as virtudes ou falhas de cada (rito), tudo isso eu declararei a vós, bem como seus bons e maus resultados em relação à descendência.` },
        { id: 'cm-3-23', number: 'Verso 23', text: `Pode-se saber que os seis primeiros de acordo com a ordem (seguida acima) são lícitos para um *Brahmana*, os quatro últimos para um *Kshatriya*, e os mesmos quatro, exceto o rito *Rakshasa*, para um *Vaisya* e um *Sudra*.` },
        { id: 'cm-3-24', number: 'Verso 24', text: `Os sábios afirmam que os quatro primeiros são aprovados (no caso) de um *Brahmana*, um, o rito *Rakshasa* (no caso) de um *Kshatriya*, e o casamento *Asura* (no) de um *Vaisya* e de um *Sudra*.` },
        { id: 'cm-3-25', number: 'Verso 25', text: `Mas nestes (Institutos da lei sagrada) três dos cinco (últimos) são declarados serem lícitos e dois ilícitos; os (ritos) *Paisaka* e o *Asura* nunca devem ser usados.` },
        { id: 'cm-3-26', number: 'Verso 26', text: `Para os *Kshatriyas* aqueles dois ritos antes mencionados, o *Gandharva* e o *Rakshasa*, quer separados quer misturados, são permitidos pela tradição sagrada.` },
        { id: 'cm-3-27', number: 'Verso 27', text: `O presente de uma filha, após adorná-la (com vestimentas caras) e honrá-la (com presentes de joias), a um homem erudito no Veda e de boa conduta, a quem (o próprio pai) convida, é chamado o rito *Brahma*.` },
        { id: 'cm-3-28', number: 'Verso 28', text: `O presente de uma filha que foi adornada com ornamentos, a um sacerdote que oficia devidamente em um sacrifício, durante o curso de sua realização, eles chamam o rito *Daiva*.` },
        { id: 'cm-3-29', number: 'Verso 29', text: `Quando (o pai) doa sua filha de acordo com a regra, após receber do noivo, para (o cumprimento da) lei sagrada, uma vaca e um touro ou dois pares, isso é nomeado o rito *Arsha*.` },
        { id: 'cm-3-30', number: 'Verso 30', text: `O presente de uma filha (por seu pai) após ele ter se dirigido (ao casal) com o texto, 'Que ambos realizem juntos seus deveres', e ter demonstrado honra (ao noivo), é chamado no *Smriti* o rito *Pragapatya*.` },
        { id: 'cm-3-31', number: 'Verso 31', text: `Quando (o noivo) recebe uma donzela, após ter dado tanta riqueza quanto pode pagar, aos parentes e à própria noiva, de acordo com sua própria vontade, isso é chamado o rito *Asura*.` },
        { id: 'cm-3-32', number: 'Verso 32', text: `A união voluntária de uma donzela e seu amante deve-se saber (ser) o rito *Gandharva*, que brota do desejo e tem a relação sexual como seu propósito.` },
        { id: 'cm-3-33', number: 'Verso 33', text: `O rapto forçado de uma donzela de seu lar, enquanto ela grita e chora, após (seus parentes) terem sido mortos ou feridos e (suas casas) arrombadas, é chamado o rito *Rakshasa*.` },
        { id: 'cm-3-34', number: 'Verso 34', text: `Quando (um homem) por furto seduz uma garota que está dormindo, intoxicada, ou com o intelecto desordenado, esse é o oitavo, o rito mais vil e pecaminoso dos Pisakas.` },
        { id: 'cm-3-35', number: 'Verso 35', text: `O presente de filhas entre os *Brahmanas* é o mais aprovado, (se for precedido) por (uma libação de) água; mas no caso de outras castas (pode ser realizado) pela (expressão de) consentimento mútuo.` },
        { id: 'cm-3-36', number: 'Verso 36', text: `Ouvi-me agora, vós *Brahmanas*, enquanto eu declaro integralmente que qualidade foi atribuída por Manu a cada um desses ritos matrimoniais.` },
        { id: 'cm-3-37', number: 'Verso 37', text: `O filho de uma esposa desposada de acordo com o rito *Brahma*, se ele realiza atos meritórios, liberta do pecado dez ancestrais, dez descendentes e a si mesmo como o vigésimo primeiro.` },
        { id: 'cm-3-38', number: 'Verso 38', text: `O filho nascido de uma esposa, desposada de acordo com o rito *Daiva*, de modo semelhante (salva) sete ancestrais e sete descendentes, o filho de uma esposa casada pelo rito *Arsha* três (nas linhas ascendente e descendente), e o filho de uma esposa casada pelo rito de Ka (Pragapati) seis (em qualquer linha).` },
        { id: 'cm-3-39', number: 'Verso 39', text: `Dos quatro casamentos, (enumerados) sucessivamente, que começam com o rito *Brahma* brotam filhos, radiantes com o conhecimento do Veda e honrados pelos *Sishtas* (homens bons).` },
        { id: 'cm-3-40', number: 'Verso 40', text: `Dotados das qualidades de beleza e bondade, possuindo riqueza e fama, obtendo tantos prazeres quantos desejam e sendo os mais justos, eles viverão cem anos.` },
        { id: 'cm-3-41', number: 'Verso 41', text: `Mas dos (quatro) casamentos censuráveis restantes brotam filhos que são cruéis e falantes de inverdades, que odeiam o Veda e a lei sagrada.` },
        { id: 'cm-3-42', number: 'Verso 42', text: `Nos casamentos irrepreensíveis crianças irrepreensíveis nascem aos homens, em (casamentos) censuráveis descendência censurável; deve-se, portanto, evitar as (formas de casamento) censuráveis.` },
        { id: 'cm-3-43', number: 'Verso 43', text: `A cerimônia de juntar as mãos é prescrita para (casamentos com) mulheres de casta igual (*varna*); sabei que a seguinte regra (aplica-se) a casamentos com fêmeas de uma casta diferente (*varna*).` },
        { id: 'cm-3-44', number: 'Verso 44', text: `Ao casar com um homem de uma casta mais alta, uma noiva *Kshatriya* deve segurar uma flecha, uma noiva *Vaisya* um aguilhão, e uma fêmea *Sudra* a bainha da veste (do noivo).` },
        { id: 'cm-3-45', number: 'Verso 45', text: `Que (o marido) se aproxime de sua esposa na devida estação, estando constantemente satisfeito com ela (apenas); ele também pode, focado em agradá-la, aproximar-se dela com o desejo de união conjugal (em qualquer dia) excetuando os Parvans.` },
        { id: 'cm-3-46', number: 'Verso 46', text: `Dezesseis (dias e) noites (em cada mês), incluindo quatro dias que diferem do resto e são censurados pelos virtuosos, (são chamados) a estação natural das mulheres.` },
        { id: 'cm-3-47', number: 'Verso 47', text: `Mas entre estes os quatro primeiros, o décimo primeiro e o décimo terceiro são (declarados serem) proibidos; as noites restantes são recomendadas.` },
        { id: 'cm-3-48', number: 'Verso 48', text: `Nas noites pares filhos são concebidos e filhas nas ímpares; daí que um homem que deseja ter filhos deve se aproximar de sua esposa na devida estação nas (noites) pares.` },
        { id: 'cm-3-49', number: 'Verso 49', text: `Um filho do sexo masculino é produzido por uma quantidade maior de semente masculina, um filho do sexo feminino pela prevalência da feminina; se (ambas são) iguais, um hermafrodita ou um menino e uma menina; se (ambas são) fracas ou deficientes em quantidade, uma falha de concepção (resulta).` },
        { id: 'cm-3-50', number: 'Verso 50', text: `Aquele que evita as mulheres nas seis noites proibidas e em oito outras, é (igual em castidade a) um estudante, em qualquer ordem que ele possa viver.` },
        { id: 'cm-3-51', number: 'Verso 51', text: `Nenhum pai que conhece (a lei) deve receber sequer a menor gratificação por sua filha; pois um homem que, por avareza, recebe uma gratificação, é um vendedor de sua descendência.` },
        { id: 'cm-3-52', number: 'Verso 52', text: `Mas aqueles parentes (masculinos) que, em sua loucura, vivem da propriedade separada das mulheres, (por exemplo, apropriam-se) das bestas de carga, carruagens, e roupas das mulheres, cometem pecado e afundarão no inferno.` },
        { id: 'cm-3-53', number: 'Verso 53', text: `Alguns chamam a vaca e o touro (dados) em um casamento *Arsha* de 'uma gratificação'; (mas) isso é errado, visto que (a aceitação de) uma taxa, seja pequena ou grande, é uma venda (da filha).` },
        { id: 'cm-3-54', number: 'Verso 54', text: `Quando os parentes não se apropriam (para seu uso) da gratificação (dada), não é uma venda; (nesse caso) o (presente) é apenas um sinal de respeito e de bondade para com as donzelas.` },
        { id: 'cm-3-55', number: 'Verso 55', text: `As mulheres devem ser honradas e adornadas por seus pais, irmãos, maridos, e cunhados, que desejam (seu próprio) bem-estar.` },
        { id: 'cm-3-56', number: 'Verso 56', text: `Onde as mulheres são honradas, lá os deuses se agradam; mas onde elas não são honradas, nenhum rito sagrado rende recompensas.` },
        { id: 'cm-3-57', number: 'Verso 57', text: `Onde as parentes do sexo feminino vivem em luto, a família logo perece totalmente; mas aquela família onde elas não são infelizes sempre prospera.` },
        { id: 'cm-3-58', number: 'Verso 58', text: `As casas nas quais as parentes do sexo feminino, não sendo devidamente honradas, pronunciam uma maldição, perecem completamente, como se destruídas por magia.` },
        { id: 'cm-3-59', number: 'Verso 59', text: `Daí que homens que buscam (seu próprio) bem-estar, devem sempre honrar as mulheres em feriados e festivais com (presentes de) ornamentos, roupas, e alimentos (delicados).` },
        { id: 'cm-3-60', number: 'Verso 60', text: `Naquela família, onde o marido está satisfeito com sua esposa e a esposa com seu marido, a felicidade será asseguradamente duradoura.` },
        { id: 'cm-3-61', number: 'Verso 61', text: `Pois se a esposa não é radiante com beleza, ela não atrairá seu marido; mas se ela não tem atrativos para ele, nenhuma criança nascerá.` },
        { id: 'cm-3-62', number: 'Verso 62', text: `Se a esposa é radiante com beleza, a casa inteira é brilhante; mas se ela é destituída de beleza, tudo parecerá lúgubre.` },
        { id: 'cm-3-63', number: 'Verso 63', text: `Por casamentos baixos, por omitir (a realização de) ritos sagrados, por negligenciar o estudo do Veda, e por irreverência para com os *Brahmanas*, (grandes) famílias afundam.` },
        { id: 'cm-3-64', number: 'Verso 64', text: `Por (praticar) ofícios manuais, por transações pecuniárias, por (gerar) filhos apenas em fêmeas *Sudras*, por (comerciar com) vacas, cavalos, e carruagens, pela (busca da) agricultura e por tomar serviço sob um rei,` },
        { id: 'cm-3-65', number: 'Verso 65', text: `Por sacrificar para homens indignos de oferecer sacrifícios e por negar (as recompensas futuras por boas) obras, as famílias, deficientes no (conhecimento do) Veda, perecem rapidamente.` },
        { id: 'cm-3-66', number: 'Verso 66', text: `Mas as famílias que são ricas no conhecimento do Veda, embora possuindo pouca riqueza, são contadas entre as grandes, e adquirem grande fama.` },
        { id: 'cm-3-67', number: 'Verso 67', text: `Com o fogo sagrado, aceso no casamento, um chefe de família deverá realizar de acordo com a lei as cerimônias domésticas e os cinco (grandes) sacrifícios, e (com aquele) ele deverá diariamente cozinhar sua comida.` },
        { id: 'cm-3-68', number: 'Verso 68', text: `Um chefe de família tem cinco matadouros (por assim dizer, a saber) a lareira, a pedra de amolar, a vassoura, o pilão e o almofariz, o recipiente de água, usando os quais ele está preso (com os grilhões do pecado).` },
        { id: 'cm-3-69', number: 'Verso 69', text: `A fim de expiar sucessivamente (as ofensas cometidas por meio) de todos estes (cinco) os grandes sábios prescreveram aos chefes de família a (realização diária dos cinco) grandes sacrifícios.` },
        { id: 'cm-3-70', number: 'Verso 70', text: `O ensino (e estudo) é o sacrifício (oferecido) a Brahman, a (oferenda de água e alimento chamada) *Tarpana* o sacrifício aos manes, a oblação queimada o sacrifício oferecido aos deuses, a oferenda *Bali* aquela oferecida aos *Bhutas*, e a recepção hospitaleira de convidados a oferenda aos homens.` },
        { id: 'cm-3-71', number: 'Verso 71', text: `Aquele que não negligencia estes cinco grandes sacrifícios, enquanto for capaz (de realizá-los), não é maculado pelos pecados (cometidos) nos cinco lugares de matança, embora ele viva constantemente na (ordem dos) chefes de família.` },
        { id: 'cm-3-72', number: 'Verso 72', text: `Mas aquele que não alimenta estes cinco, os deuses, seus convidados, aqueles que ele é obrigado a sustentar, os manes, e a si mesmo, não vive, embora respire.` },
        { id: 'cm-3-73', number: 'Verso 73', text: `Eles chamam (estes) cinco sacrifícios também de, *Ahuta*, *Huta*, *Prahuta*, *Brahmya-huta*, e *Prasita*.` },
        { id: 'cm-3-74', number: 'Verso 74', text: `*Ahuta* (não oferecido no fogo) é a murmuração (de textos Védicos), *Huta* a oblação queimada (oferecida aos deuses), *Prahuta* (oferecido espalhando-o no chão) a oferenda *Bali* dada aos *Bhutas*, *Brahmya-huta* (oferecido no fogo digestivo dos *Brahmanas*), a recepção respeitosa de (convidados) *Brahmanas*, e *Prasita* (comido) a (oblação diária aos manes, chamada) *Tarpana*.` },
        { id: 'cm-3-75', number: 'Verso 75', text: `Que (todo homem) nesta (segunda ordem, ao menos) aplique-se diariamente à recitação particular do Veda, e também à realização da oferenda aos deuses; pois aquele que é diligente na realização de sacrifícios, sustenta tanto a criação móvel quanto a imóvel.` },
        { id: 'cm-3-76', number: 'Verso 76', text: `Uma oblação devidamente atirada no fogo, alcança o sol; do sol vem a chuva, da chuva o alimento, daí as criaturas vivas (derivam sua subsistência).` },
        { id: 'cm-3-77', number: 'Verso 77', text: `Como todas as criaturas vivas subsistem por receber sustento do ar, mesmo assim (os membros de) todas as ordens subsistem por receber sustento do chefe de família.` },
        { id: 'cm-3-78', number: 'Verso 78', text: `Porque os homens das três (outras) ordens são diariamente sustentados pelo chefe de família com (presentes de) conhecimento sagrado e alimento, portanto (a ordem dos) chefes de família é a mais excelente ordem.` },
        { id: 'cm-3-79', number: 'Verso 79', text: `(Os deveres de) esta ordem, que não podem ser praticados por homens com órgãos fracos, devem ser cuidadosamente observados por aquele que deseja a (bem-aventurança) imperecível no céu, e a felicidade constante nesta (vida).` },
        { id: 'cm-3-80', number: 'Verso 80', text: `Os sábios, os manes, os deuses, os *Bhutas*, e os convidados pedem aos chefes de família (por oferendas e presentes); daí aquele que conhece (a lei), deve dar a eles (o que é devido a cada um).` },
        { id: 'cm-3-81', number: 'Verso 81', text: `Que ele adore, de acordo com a regra, os sábios pela recitação particular do Veda, os deuses por oblações queimadas, os manes por oferendas fúnebres (*Sraddha*), os homens por (presentes de) alimento, e os *Bhutas* pela oferenda *Bali*.` },
        { id: 'cm-3-82', number: 'Verso 82', text: `Que ele realize diariamente um sacrifício fúnebre com alimento, ou com água, ou também com leite, raízes, e frutas, e (assim) agrade aos manes.` },
        { id: 'cm-3-83', number: 'Verso 83', text: `Que ele alimente até mesmo um *Brahmana* em honra aos manes no (*Sraddha*), que pertence aos cinco grandes sacrifícios; mas que ele não alimente nessa (ocasião) nenhum *Brahmana* por causa da oferenda *Vaisvadeva*.` },
        { id: 'cm-3-84', number: 'Verso 84', text: `Um *Brahmana* deverá oferecer de acordo com a regra (de seu *Grihya-sutra* uma porção) da comida cozida destinada ao *Vaisvadeva* no fogo doméstico sagrado às seguintes deidades:` },
        { id: 'cm-3-85', number: 'Verso 85', text: `Primeiro a Agni, e (a seguir) a Soma, então a ambos estes deuses conjuntamente, além disso a todos os deuses (*Visve Devah*), e (então) a Dhanvantari,` },
        { id: 'cm-3-86', number: 'Verso 86', text: `Além disso a Kuhu (a deusa do dia de lua nova), a Anumati (a deusa do dia de lua cheia), a Pragapati (o senhor das criaturas), ao céu e à terra conjuntamente, e finalmente a Agni Svishtakrit (o fogo que realiza o sacrifício bem).` },
        { id: 'cm-3-87', number: 'Verso 87', text: `Após ter assim devidamente oferecido o alimento sacrificial, que ele jogue oferendas *Bali* em todas as direções da bússola, procedendo (do leste) para o sul, a Indra, Yama, Varuna, e Soma, bem como aos servos (destas deidades).` },
        { id: 'cm-3-88', number: 'Verso 88', text: `Dizendo, '(Adoração) aos Maruts', ele espalhará (algum alimento) perto da porta, e (algum) na água, dizendo, '(Adoração) às águas'; ele atirará (algum) no pilão e no almofariz, falando assim, '(Adoração) às árvores'.` },
        { id: 'cm-3-89', number: 'Verso 89', text: `Perto da cabeceira (da cama) ele fará uma oferenda a Sri (fortuna), e perto do pé (de sua cama) a Bhadrakali; no centro da casa que ele coloque um *Bali* para Brahman e para Vastoshpati (o senhor da habitação) conjuntamente.` },
        { id: 'cm-3-90', number: 'Verso 90', text: `Que ele jogue para o ar um *Bali* para todos os deuses, e (durante o dia um) para os duendes que perambulam de dia, (e à noite um) para os duendes que andam à noite.` },
        { id: 'cm-3-91', number: 'Verso 91', text: `No andar superior que ele ofereça um *Bali* a Sarvatmabhuti; mas que ele jogue o que resta (destas oferendas) na direção sul para os manes.` },
        { id: 'cm-3-92', number: 'Verso 92', text: `Que ele coloque gentilmente no chão (algum alimento) para cães, párias, *Kandalas* (*Svapak*), aqueles afligidos com doenças que são punições de pecados anteriores, corvos, e insetos.` },
        { id: 'cm-3-93', number: 'Verso 93', text: `Aquele *Brahmana* que assim honra diariamente a todos os seres, vai, dotado de um corpo resplandecente, por uma estrada reta para o mais alto local de morada (isto é, Brahman).` },
        { id: 'cm-3-94', number: 'Verso 94', text: `Tendo realizado esta oferenda *Bali*, ele primeiro alimentará seu convidado e, de acordo com a regra, dará esmolas a um asceta (e) a um estudante.` },
        { id: 'cm-3-95', number: 'Verso 95', text: `Um chefe de família duas-vezes-nascido ganha, dando esmolas, a mesma recompensa por seu ato meritório que (um estudante) obtém por apresentar, de acordo com a regra, uma vaca ao seu professor.` },
        { id: 'cm-3-96', number: 'Verso 96', text: `Que ele dê, de acordo com a regra, a um *Brahmana* que conhece o verdadeiro significado do Veda, mesmo (uma pequena porção de alimento como) esmola, ou um pote cheio de água, tendo guarnecido (o alimento com tempero, ou o pote com flores e frutas).` },
        { id: 'cm-3-97', number: 'Verso 97', text: `As oblações aos deuses e manes, feitas por homens ignorantes (da lei dos presentes), são perdidas, se os doadores em sua loucura apresentarem (porções delas) aos *Brahmanas* que são meras cinzas.` },
        { id: 'cm-3-98', number: 'Verso 98', text: `Uma oferenda feita no fogo da boca de *Brahmanas* ricos em aprendizado sagrado e austeridades, salva do infortúnio e de grande culpa.` },
        { id: 'cm-3-99', number: 'Verso 99', text: `Mas que ele ofereça, de acordo com a regra, a um convidado que chegou (por sua própria vontade) um assento e água, assim como alimento, guarnecido (com tempero), de acordo com sua capacidade.` },
        { id: 'cm-3-100', number: 'Verso 100', text: `Um *Brahmana* que permanece não honrado (na casa), leva embora (consigo) todo o mérito espiritual mesmo de um homem que subsiste respigando espigas de milho, ou oferece oblações em cinco fogos.` },
        { id: 'cm-3-101', number: 'Verso 101', text: `Grama, um cômodo (para descanso), água, e em quarto lugar uma palavra gentil; estas (coisas) nunca faltam nas casas de homens bons.` },
        { id: 'cm-3-102', number: 'Verso 102', text: `Mas um *Brahmana* que fica apenas uma noite é declarado ser um convidado (*atithi*); pois, porque ele não fica (*sthita*) muito tempo (*anityam*), ele é chamado *atithi* (um convidado).` },
        { id: 'cm-3-103', number: 'Verso 103', text: `Não se deve considerar como convidado um *Brahmana* que habita na mesma vila, nem aquele que busca seu sustento através da interação social, mesmo que ele tenha chegado a uma casa onde (haja) uma esposa, e onde fogos sagrados (são mantidos).` },
        { id: 'cm-3-104', number: 'Verso 104', text: `Aqueles chefes de família tolos que constantemente buscam (viver do) alimento dos outros, tornam-se, em consequência dessa (vileza), após a morte o gado daqueles que lhes dão alimento.` },
        { id: 'cm-3-105', number: 'Verso 105', text: `Um convidado que é enviado pelo sol (poente) à noite, não deve ser enxotado por um chefe de família; quer ele tenha chegado na hora (da ceia) ou num momento inoportuno, ele não deve ficar na casa sem hospitalidade.` },
        { id: 'cm-3-106', number: 'Verso 106', text: `Que ele não coma qualquer alimento (delicado) que não ofereça a seu convidado; a recepção hospitaleira de convidados proporciona riqueza, fama, vida longa, e bem-aventurança celestial.` },
        { id: 'cm-3-107', number: 'Verso 107', text: `Que ele ofereça (aos seus convidados) assentos, quartos, camas, atendimento na partida e honra (enquanto ficam), aos mais distintos na melhor forma, aos inferiores numa forma inferior, aos iguais de uma maneira igual.` },
        { id: 'cm-3-108', number: 'Verso 108', text: `Mas se outro convidado chegar depois que a oferenda *Vaisvadeva* tiver terminado, (o chefe de família) deve dar-lhe alimento de acordo com sua capacidade, (mas) não repetir a oferenda *Bali*.` },
        { id: 'cm-3-109', number: 'Verso 109', text: `Um *Brahmana* não deverá nomear sua família e (seu *gotra* Védico) a fim de obter uma refeição; pois aquele que se gaba deles em prol de uma refeição, é chamado pelos sábios de um alimentador imundo (*vantasin*).` },
        { id: 'cm-3-110', number: 'Verso 110', text: `Mas um *Kshatriya* (que vem) à casa de um *Brahmana* não é chamado de convidado (*atithi*), nem um *Vaisya*, nem um *Sudra*, nem um amigo pessoal, nem um parente, nem o professor.` },
        { id: 'cm-3-111', number: 'Verso 111', text: `Mas se um *Kshatriya* vem à casa de um *Brahmana* na maneira de um convidado, (o chefe de família) pode alimentá-lo de acordo com seu desejo, depois que os *Brahmanas* mencionados acima tiverem comido.` },
        { id: 'cm-3-112', number: 'Verso 112', text: `Até mesmo a um *Vaisya* e a um *Sudra* que tiverem se aproximado de sua casa na maneira de convidados, ele pode permitir comer com seus servos, mostrando (com isso) sua disposição compassiva.` },
        { id: 'cm-3-113', number: 'Verso 113', text: `Mesmo a outros, amigos pessoais e afins, que tiverem vindo à sua casa por afeto, ele pode dar alimento, guarnecido (com tempero) de acordo com sua capacidade, (ao mesmo tempo) com sua esposa.` },
        { id: 'cm-3-114', number: 'Verso 114', text: `Sem hesitação ele pode dar alimento, mesmo antes de seus convidados, às seguintes pessoas, (a saber) a mulheres recém-casadas, a crianças de colo, aos doentes, e a mulheres grávidas.` },
        { id: 'cm-3-115', number: 'Verso 115', text: `Mas o homem tolo que come primeiro sem ter dado alimento a estas (pessoas) não sabe, enquanto se empanturra, que (após a morte) ele mesmo será devorado por cães e abutres.` },
        { id: 'cm-3-116', number: 'Verso 116', text: `Depois que os *Brahmanas*, os parentes, e os servos tiverem jantado, o chefe de família e sua esposa podem depois comer o que restar.` },
        { id: 'cm-3-117', number: 'Verso 117', text: `Tendo honrado os deuses, os sábios, os homens, os manes, e as divindades guardiãs da casa, o chefe de família deverá comer depois o que restar.` },
        { id: 'cm-3-118', number: 'Verso 118', text: `Aquele que prepara o alimento (só) para si mesmo, não come nada senão pecado; pois está ordenado que o alimento que resta após (a realização d)os sacrifícios será a refeição de homens virtuosos.` },
        { id: 'cm-3-119', number: 'Verso 119', text: `Que ele honre com a mistura de mel um rei, um sacerdote oficiante, um *Snataka*, o professor, um genro, um sogro, e um tio materno, (se eles vierem) novamente após um ano inteiro (ter se passado desde sua última visita).` },
        { id: 'cm-3-120', number: 'Verso 120', text: `Um rei e um *Srotriya*, que vêm para a realização de um sacrifício, devem ser honrados com a mistura de mel, mas não se nenhum sacrifício estiver sendo realizado; essa é uma regra estabelecida.` },
        { id: 'cm-3-121', number: 'Verso 121', text: `Mas a esposa oferecerá à noite (uma porção) do alimento preparado como uma oblação *Bali*, sem (a recitação de) fórmulas sagradas; pois aquele (rito que é chamado de) *Vaisvadeva* é prescrito tanto para a manhã quanto para a noite.` },
        { id: 'cm-3-122', number: 'Verso 122', text: `Após realizar o *Pitriyagna*, um *Brahmana* que mantém um fogo sagrado oferecerá, mês a mês, no dia de lua nova, o sacrifício fúnebre (*Sraddha*, chamado) *Pindanvaharyaka*.` },
        { id: 'cm-3-123', number: 'Verso 123', text: `Os sábios chamam a oferenda fúnebre mensal aos manes de *Anvaharya* (a ser oferecida após os bolos), e isso deve ser cuidadosamente realizado com as (espécies de) carne aprovadas (mencionadas abaixo).` },
        { id: 'cm-3-124', number: 'Verso 124', text: `Eu declararei integralmente o que e quantos (*Brahmanas*) devem ser alimentados nessa (ocasião), quem deve ser evitado, e em que tipos de alimento (eles jantarão).` },
        { id: 'cm-3-125', number: 'Verso 125', text: `Deve-se alimentar dois (*Brahmanas*) na oferenda aos deuses, e três na oferenda aos manes, ou apenas um em qualquer ocasião; mesmo um homem muito rico não deverá estar ansioso para (entreter) uma grande companhia.` },
        { id: 'cm-3-126', number: 'Verso 126', text: `Uma grande companhia destrói estas cinco (vantagens): o tratamento respeitoso (dos convidados, a propriedade do) lugar e do tempo, a pureza e (a seleção de convidados) *Brahmanas* virtuosos; ele, portanto, não buscará (entreter) uma grande companhia.` },
        { id: 'cm-3-127', number: 'Verso 127', text: `Famoso é este rito para os mortos, chamado (o sacrifício sagrado aos manes e realizado) no dia de lua nova; se um homem for diligente em (realizá-lo), (a recompensa do) rito para os mortos, que é realizado de acordo com as regras *Smarta*, o alcança constantemente.` },
        { id: 'cm-3-128', number: 'Verso 128', text: `Oblações aos deuses e manes devem ser apresentadas pelos doadores apenas a um *Srotriya*; o que é dado a tal *Brahmana* mui digno rende grande recompensa.` },
        { id: 'cm-3-129', number: 'Verso 129', text: `Que ele alimente apenas um homem erudito no (sacrifício) aos deuses, e um no (sacrifício) aos manes; (assim) ele ganhará uma rica recompensa, não (se ele entretiver) muitos que não estão familiarizados com o Veda.` },
        { id: 'cm-3-130', number: 'Verso 130', text: `Que ele faça indagações mesmo a respeito dos remotos (ancestrais de) um *Brahmana* que estudou uma (recensão) inteira do Veda; (se descendido de uma raça virtuosa) tal homem é um recipiente digno de presentes (consistentes) de comida oferecida aos deuses ou aos manes, ele é declarado (providenciar tão grandes recompensas quanto) um convidado (*atithi*).` },
        { id: 'cm-3-131', number: 'Verso 131', text: `Embora um milhão de homens, não familiarizados com os *Rikas*, fosse jantar em um (sacrifício fúnebre), no entanto, um único homem, erudito no Veda, que está satisfeito (com o entretenimento), vale mais que todos eles no que tange (à produção do) mérito espiritual.` },
        { id: 'cm-3-132', number: 'Verso 132', text: `O alimento sagrado para os manes ou para os deuses deve ser dado a um homem distinguido pelo conhecimento sagrado; pois mãos manchadas com sangue, não podem ser limpas com sangue.` },
        { id: 'cm-3-133', number: 'Verso 133', text: `Tantos bocados quantos um homem ignorante engolir em um sacrifício aos deuses ou aos manes, tantos espetos incandescente, lanças e bolas de ferro deve (o doador do repasto) engolir após a morte.` },
        { id: 'cm-3-134', number: 'Verso 134', text: `Alguns *Brahmanas* são devotados à (busca do) conhecimento, e outros à (realização de) austeridades; alguns às austeridades e à recitação do Veda, e outros à (realização de) ritos sagrados.` },
        { id: 'cm-3-135', number: 'Verso 135', text: `As oblações aos manes deveriam ser cuidadosamente apresentadas àqueles devotados ao conhecimento, mas as oferendas aos deuses, de acordo com a razão (da lei sagrada), a (homens d)as quatro (classes mencionadas acima).` },
        { id: 'cm-3-136', number: 'Verso 136', text: `Se há um pai ignorante dos textos sagrados cujo filho aprendeu uma recensão inteira do Veda e dos *Angas*, e um filho ignorante dos textos sagrados cujo pai conhece uma recensão inteira do Veda e dos *Angas*,` },
        { id: 'cm-3-137', number: 'Verso 137', text: `Sabe que aquele cujo pai conhece o Veda, é o mais venerável (dos dois); porém o outro é digno de honra, porque o respeito é devido ao Veda (que ele aprendeu).` },
        { id: 'cm-3-138', number: 'Verso 138', text: `Que ele não entretenha um amigo pessoal num sacrifício fúnebre; ele pode ganhar a afeição dele por (outros) presentes valiosos; que ele alimente num *Sraddha* a um *Brahmana* que ele não considera nem como inimigo nem como amigo.` },
        { id: 'cm-3-139', number: 'Verso 139', text: `Aquele que realiza sacrifícios fúnebres e oferendas aos deuses principalmente pelo bem de (ganhar) amigos, não colhe após a morte recompensa por *Sraddhas* e sacrifícios.` },
        { id: 'cm-3-140', number: 'Verso 140', text: `Aquele mais vil entre os homens duas-vezes-nascidos que em sua tolice contrai amizades através de um sacrifício fúnebre, perde o céu, porque ele realizou um *Sraddha* pelo bem da amizade.` },
        { id: 'cm-3-141', number: 'Verso 141', text: `Um presente (de comida) por homens duas-vezes-nascidos, consumido com (amigos e parentes), diz-se ser oferecido aos Pisakas; ele permanece neste (mundo) apenas, como uma vaca cega num único estábulo.` },
        { id: 'cm-3-142', number: 'Verso 142', text: `Como um marido que não colhe safra quando semeou a semente num solo estéril, assim também o doador do alimento sacrificial não ganha recompensa se ele o apresentou a um homem não familiarizado com os *Rikas*.` },
        { id: 'cm-3-143', number: 'Verso 143', text: `Mas um presente feito de acordo com as regras a um homem erudito, torna o doador e o recebedor parceiros de recompensas tanto nesta (vida) quanto após a morte.` },
        { id: 'cm-3-144', number: 'Verso 144', text: `(Se nenhum *Brahmana* erudito estiver à mão), ele deveria antes honrar a um amigo (virtuoso) que a um inimigo, embora o último possa ser qualificado (por aprendizado e afins); pois comida sacrificial, comida por um inimigo, não gera recompensa após a morte.` },
        { id: 'cm-3-145', number: 'Verso 145', text: `Que ele (tome) o trabalho (de) alimentar num *Sraddha* um aderente do *Rig-veda* que estudou uma (recensão inteira desse) Veda, ou um seguidor do *Yagur-veda* que terminou uma *Sakha*, ou um cantor de *Samans* que (igualmente) completou (o estudo de uma recensão inteira).` },
        { id: 'cm-3-146', number: 'Verso 146', text: `Se um destes três janta, devidamente honrado, num sacrifício fúnebre, os ancestrais daquele (que dá a festa), até a sétima pessoa, ficarão satisfeitos por muito tempo.` },
        { id: 'cm-3-147', number: 'Verso 147', text: `Esta é a regra principal (a ser seguida) ao oferecer sacrifícios aos deuses e manes; saiba que os virtuosos sempre observam a seguinte regra subsidiária.` },
        { id: 'cm-3-148', number: 'Verso 148', text: `Alguém também pode entreter (em tais ocasiões) o avô materno de alguém, um tio materno, o filho de uma irmã, um sogro, o professor de alguém, o filho de uma filha, o marido de uma filha, um parente cognato, seu próprio padre oficiante ou um homem para quem ele oferece sacrifícios.` },
        { id: 'cm-3-149', number: 'Verso 149', text: `Para um rito sagrado para os deuses, ele que conhece a lei não fará (muito perto) indagações a respeito de um *Brahmana* (convidado); mas quando alguém realiza uma cerimônia em honra aos manes, ele deve examinar cuidadosamente (as qualidades e filiação do convidado).` },
        { id: 'cm-3-150', number: 'Verso 150', text: `Manu declarou que aqueles *Brahmanas* que são ladrões, párias, eunucos, ou ateus são indignos (para participar) das oblações aos deuses e manes.` },
        { id: 'cm-3-151', number: 'Verso 151', text: `Que ele não entretenha em um *Sraddha* aquele que usa seu cabelo em tranças (um estudante), aquele que não estudou (o Veda), um afligido com uma doença de pele, um jogador, nem aqueles que sacrificam para uma multidão (de sacrificadores).` },
        { id: 'cm-3-152', number: 'Verso 152', text: `Médicos, sacerdotes de templo, vendedores de carne, e aqueles que subsistem por manter lojas devem ser evitados em sacrifícios oferecidos aos deuses e aos manes.` },
        { id: 'cm-3-153', number: 'Verso 153', text: `Um servo pago de uma vila ou de um rei, um homem com unhas deformadas ou dentes negros, aquele que se opõe ao seu professor, aquele que abandonou o fogo sagrado, e um usurário;` },
        { id: 'cm-3-154', number: 'Verso 154', text: `Alguém sofrendo de tísica, aquele que subsiste cuidando de gado, um irmão mais novo que se casa ou acende o fogo sagrado antes do mais velho, aquele que negligencia os cinco grandes sacrifícios, um inimigo da raça *Brahmana*, um irmão mais velho que se casa ou acende o fogo sagrado depois do mais novo, e aquele que pertence a uma companhia ou corporação,` },
        { id: 'cm-3-155', number: 'Verso 155', text: `Um ator ou cantor, aquele que quebrou o voto de aprendizado, aquele cuja (única ou primeira) esposa é uma fêmea *Sudra*, o filho de uma mulher recasada, um homem de um olho só, e ele em cuja casa um amante de sua esposa (reside);` },
        { id: 'cm-3-156', number: 'Verso 156', text: `Aquele que ensina por uma taxa estipulada e aquele que é ensinado sob essa condição, aquele que instrui pupilos *Sudras* e aquele cujo professor é um *Sudra*, aquele que fala rudemente, o filho de uma adúltera, e o filho de uma viúva,` },
        { id: 'cm-3-157', number: 'Verso 157', text: `Aquele que abandona sua mãe, seu pai, ou um professor sem uma razão (suficiente), aquele que contraiu uma aliança com párias quer através do Veda quer através de um casamento,` },
        { id: 'cm-3-158', number: 'Verso 158', text: `Um incendiário, um prisioneiro, aquele que come a comida dada pelo filho de uma adúltera, um vendedor de *Soma*, aquele que empreende viagens por mar, um bardo, um homem do óleo, um subornador para perjúrio,` },
        { id: 'cm-3-159', number: 'Verso 159', text: `Aquele que briga ou vai à lei contra seu pai, o mantenedor de uma casa de jogos, um bêbado, aquele que é afligido com uma doença (em punição de) crimes (anteriores), aquele que é acusado de um pecado mortal, um hipócrita, um vendedor de substâncias usadas para dar sabor à comida,` },
        { id: 'cm-3-160', number: 'Verso 160', text: `Um fabricante de arcos e de flechas, aquele que lascivamente flerta com a viúva de um irmão, o traidor de um amigo, aquele que subsiste do jogo, aquele que aprende (o Veda) de seu filho,` },
        { id: 'cm-3-161', number: 'Verso 161', text: `Um homem epiléptico, que sofre de inchaços escrofulosos das glândulas, um afligido com lepra branca, um informante, um louco, um cego, e aquele que critica o Veda devem (todos) ser evitados.` },
        { id: 'cm-3-162', number: 'Verso 162', text: `Um treinador de elefantes, bois, cavalos, ou camelos, aquele que subsiste da astrologia, um criador de pássaros, e aquele que ensina o uso de armas,` },
        { id: 'cm-3-163', number: 'Verso 163', text: `Aquele que desvia cursos d'água, e aquele que se deleita em obstruí-los, um arquiteto, um mensageiro, e aquele que planta árvores (por dinheiro),` },
        { id: 'cm-3-164', number: 'Verso 164', text: `Um criador de cães de caça, um falcoeiro, aquele que profana donzelas, aquele que se deleita em ferir criaturas vivas, aquele que ganha sua subsistência de *Sudras*, e aquele que oferece sacrifícios aos *Ganas*,` },
        { id: 'cm-3-165', number: 'Verso 165', text: `Aquele que não segue a regra de conduta, um (homem destituído de energia como um) eunuco, aquele que constantemente pede (por favores), aquele que vive da agricultura, um homem com pé torto, e aquele que é censurado por homens virtuosos,` },
        { id: 'cm-3-166', number: 'Verso 166', text: `Um pastor, um tratador de búfalos, o marido de uma mulher recasada, e um carregador de corpos mortos, (todos estes) devem ser cuidadosamente evitados.` },
        { id: 'cm-3-167', number: 'Verso 167', text: `Um *Brahmana* que conhece (a lei sagrada) deve evitar nos (sacrifícios) tanto (aos deuses quanto aos manes) estes mais baixos dos homens duas-vezes-nascidos, cuja conduta é repreensível, e que são indignos (de sentar-se) na companhia (em um repasto).` },
        { id: 'cm-3-168', number: 'Verso 168', text: `Como um fogo de grama seca é (incapaz de consumir as oferendas e é rapidamente) extinto, mesmo assim (é com) um *Brahmana* não instruído; a comida sacrificial não deve ser dada a ele, visto que (seria) oferecida em cinzas.` },
        { id: 'cm-3-169', number: 'Verso 169', text: `Eu declararei integralmente qual resultado o doador obtém após a morte, se ele dá comida, destinada aos deuses ou manes, a um homem que é indigno de sentar-se na companhia.` },
        { id: 'cm-3-170', number: 'Verso 170', text: `Os *Rakshasas*, de fato, consomem (a comida) comida por *Brahmanas* que não cumpriram o voto de aprendizado, por um *Parivettri* e assim por diante, e por outros homens não admissíveis na companhia.` },
        { id: 'cm-3-171', number: 'Verso 171', text: `Ele deve ser considerado como um *Parivettri* que se casa ou começa a realização do *Agnihotra* antes de seu irmão mais velho, mas este último como um *Parivitti*.` },
        { id: 'cm-3-172', number: 'Verso 172', text: `O irmão mais velho que se casa depois do mais novo, o irmão mais novo que se casa antes do mais velho, a fêmea com quem tal casamento é contraído, aquele que a entrega, e o sacerdote sacrificador, como o quinto, todos caem no inferno.` },
        { id: 'cm-3-173', number: 'Verso 173', text: `Aquele que lascivamente flerta com a viúva de um irmão falecido, embora ela seja designada (para gerar um filho dele) de acordo com a lei sagrada, deve ser conhecido por ser um *Didhishupati*.` },
        { id: 'cm-3-174', number: 'Verso 174', text: `Dois (tipos de) filhos, um *Kunda* e um *Golaka*, nascem de esposas de outros homens; (aquele que nasce) enquanto o marido vive, será um *Kunda*, e (aquele que é gerado) após a morte do marido, um *Golaka*.` },
        { id: 'cm-3-175', number: 'Verso 175', text: `Mas essas duas criaturas, que nascem de esposas de outros homens, causam ao doador a perda (das recompensas), tanto nesta vida quanto após a morte, pela comida sagrada aos deuses ou manes que foi dada (a eles).` },
        { id: 'cm-3-176', number: 'Verso 176', text: `O doador tolo (de um repasto fúnebre) não colhe a recompensa por tantos convidados dignos quantos um homem, inadmissível na companhia, puder olhar enquanto estão se alimentando.` },
        { id: 'cm-3-177', number: 'Verso 177', text: `Um homem cego por sua presença causa ao doador (da festa) a perda da recompensa por noventa (convidados), um homem de um olho só por sessenta, um que sofre de lepra branca por cem, e um punido por uma doença (terrível) por mil.` },
        { id: 'cm-3-178', number: 'Verso 178', text: `O doador (de um *Sraddha*) perde a recompensa, devida por tal presente não-sacrificial, para tantos *Brahmanas* quantos um (convidado) que sacrifica para *Sudras* possa tocar (durante a refeição) com seus membros.` },
        { id: 'cm-3-179', number: 'Verso 179', text: `E se um *Brahmana*, embora erudito no Veda, aceita por avidez um presente de tal (homem), ele perecerá rapidamente, como um vaso de argila não queimada na água.` },
        { id: 'cm-3-180', number: 'Verso 180', text: `(Comida) dada a um vendedor de *Soma* torna-se excremento, (aquela dada) a um médico pus e sangue, mas (aquela apresentada) a um sacerdote de templo é perdida, e (aquela dada) a um usurário não encontra lugar (no mundo dos deuses).` },
        { id: 'cm-3-181', number: 'Verso 181', text: `O que foi dado a um *Brahmana* que vive do comércio que não é (útil) neste mundo e no próximo, e (um presente) a um *Brahmana* nascido de uma mulher recasada (assemelha-se a) uma oblação atirada em cinzas.` },
        { id: 'cm-3-182', number: 'Verso 182', text: `Mas os sábios declaram que a comida que (é oferecida) a outros homens impuros, inadmissíveis, enumerados acima, (é transformada em) secreções adiposas, sangue, carne, medula, e osso.` },
        { id: 'cm-3-183', number: 'Verso 183', text: `Agora ouvi por qual chefe dos homens duas-vezes-nascidos uma companhia profanada pela (presença de) (convidados) indignos é purificada, e a (descrição) integral dos *Brahmanas* que santificam uma companhia.` },
        { id: 'cm-3-184', number: 'Verso 184', text: `Aqueles homens devem ser considerados como os santificadores de uma companhia que são os mais eruditos em todos os Vedas e em todos os *Angas*, e que são os descendentes de *Srotriyas*.` },
        { id: 'cm-3-185', number: 'Verso 185', text: `Um *Trinakiketa*, aquele que mantém cinco fogos sagrados, um *Trisuparna*, aquele que é versado nos seis *Angas*, o filho de uma mulher casada de acordo com o rito *Brahma*, aquele que canta o *Gyeshthasaman*,` },
        { id: 'cm-3-186', number: 'Verso 186', text: `Aquele que conhece o significado do Veda, e aquele que o expõe, um estudante, aquele que doou mil (vacas), e um centenário devem ser considerados como *Brahmanas* que santificam uma companhia.` },
        { id: 'cm-3-187', number: 'Verso 187', text: `No dia anterior à realização do rito *Sraddha*, ou no dia em que ele ocorre, que ele convide com devido respeito pelo menos três *Brahmanas*, tais como foram mencionados acima.` },
        { id: 'cm-3-188', number: 'Verso 188', text: `Um *Brahmana* que foi convidado a um (rito) em honra aos manes deverá sempre se controlar e não recitar o Veda, e aquele que realiza o *Sraddha* (deve agir da mesma maneira).` },
        { id: 'cm-3-189', number: 'Verso 189', text: `Pois os manes assistem os *Brahmanas* convidados, os seguem (quando caminham) como o vento, e sentam-se perto deles quando estão sentados.` },
        { id: 'cm-3-190', number: 'Verso 190', text: `Mas um *Brahmana* que, sendo devidamente convidado a um rito em honra aos deuses ou aos manes, de qualquer forma quebra (o compromisso), torna-se culpado (de um crime), e (em seu próximo nascimento) um porco.` },
        { id: 'cm-3-191', number: 'Verso 191', text: `Mas aquele que, sendo convidado a um *Sraddha*, flerta com uma mulher *Sudra*, toma sobre si todos os pecados que o doador (da festa) cometeu.` },
        { id: 'cm-3-192', number: 'Verso 192', text: `Os manes são deidades primordiais, livres de ira, cuidadosos com a pureza, sempre castos, avessos a contendas, e dotados de grandes virtudes.` },
        { id: 'cm-3-193', number: 'Verso 193', text: `Agora aprendei integralmente de quem todos estes (manes derivam) sua origem, e com que cerimônias eles devem ser adorados.` },
        { id: 'cm-3-194', number: 'Verso 194', text: `As (várias) classes dos manes são declaradas serem os filhos de todos aqueles sábios, *Mariki* e os demais, que são filhos de Manu, o filho de Hiranyagarbha.` },
        { id: 'cm-3-195', number: 'Verso 195', text: `Os *Somasads*, os filhos de Virag, são declarados serem os manes dos *Sadhyas*, e os *Agnishvattas*, os filhos de *Mariki*, são famosos no mundo (como os manes) dos deuses.` },
        { id: 'cm-3-196', number: 'Verso 196', text: `Os *Barhishads*, nascidos de Atri, são registrados como sendo (os manes) dos *Daityas*, *Danavas*, *Yakshas*, *Gandharvas*, Deidades-serpente, *Rakshasas*, *Suparnas*, e *Kimnaras*,` },
        { id: 'cm-3-197', number: 'Verso 197', text: `Os *Somapas* os dos *Brahmanas*, os *Havirbhugs* os dos *Kshatriyas*, os *Agyapas* os dos *Vaisyas*, mas os *Sukalins* os dos *Sudras*.` },
        { id: 'cm-3-198', number: 'Verso 198', text: `Os *Somapas* são os filhos de Kavi (Bhrigu), os *Havishmats* os filhos de Angiras, os *Agyapas* a descendência de Pulastya, mas os *Sukalins* (a prole) de Vasishtha.` },
        { id: 'cm-3-199', number: 'Verso 199', text: `Deve-se saber que (outras classes), os *Agnidagdhas*, os *Anagnidagdhas*, os *Kavyas*, os *Barhishads*, os *Agnishvattas*, e os *Saumyas*, são (os manes) dos *Brahmanas* apenas.` },
        { id: 'cm-3-200', number: 'Verso 200', text: `Mas sabei também que existem neste (mundo) incontáveis filhos e netos daquelas principais classes de manes que foram enumeradas.` },
        { id: 'cm-3-201', number: 'Verso 201', text: `Dos sábios brotaram os manes, dos manes os deuses e os *Danavas*, mas dos deuses o mundo inteiro, tanto o móvel quanto o imóvel na devida ordem.` },
        { id: 'cm-3-202', number: 'Verso 202', text: `Até mesmo água oferecida com fé (aos manes) em vasos feitos de prata ou adornados com prata, produz infindável (bem-aventurança).` },
        { id: 'cm-3-203', number: 'Verso 203', text: `Para os homens duas-vezes-nascidos o rito em honra aos manes é mais importante do que o rito em honra aos deuses; pois a oferenda aos deuses que precede (os *Sraddhas*), foi declarada ser um meio de fortificar (os últimos).` },
        { id: 'cm-3-204', number: 'Verso 204', text: `Que ele primeiro convide um (*Brahmana*) em honra aos deuses como uma proteção para a (oferenda aos manes); pois os *Rakshasas* destroem um sacrifício fúnebre que é deixado sem tal proteção.` },
        { id: 'cm-3-205', number: 'Verso 205', text: `Que ele faça (o *Sraddha*) começar e terminar com (um rito) em honra aos deuses; ele não deverá começar e terminar com um (rito) aos manes; pois aquele que o faz começar e terminar com um (rito) em honra aos manes, rapidamente perece junto com sua progênie.` },
        { id: 'cm-3-206', number: 'Verso 206', text: `Que ele manche um lugar puro e recluso com esterco de vaca, e cuidadosamente o faça inclinado em direção ao sul.` },
        { id: 'cm-3-207', number: 'Verso 207', text: `Os manes estão sempre satisfeitos com oferendas feitas em lugares abertos, naturalmente puros, nas margens de rios, e em locais reclusos.` },
        { id: 'cm-3-208', number: 'Verso 208', text: `O (sacrificador) deverá fazer os *Brahmanas* (convidados), que devidamente realizaram suas abluções, sentar-se em assentos separados e preparados, sobre os quais lâminas de grama *Kusa* foram colocadas.` },
        { id: 'cm-3-209', number: 'Verso 209', text: `Tendo colocado esses *Brahmanas* irrepreensíveis em seus assentos, ele deverá honrá-los com guirlandas fragrantes e perfumes, começando com (aqueles que são convidados em honra aos) deuses.` },
        { id: 'cm-3-210', number: 'Verso 210', text: `Tendo apresentado a eles água, grãos de gergelim, e lâminas de grama *Kusa*, o (sacrificador) *Brahmana* deverá oferecer (oblações) no fogo sagrado, após ter recebido permissão (para fazê-lo) de (todos os) (convidados) *Brahmanas* conjuntamente.` },
        { id: 'cm-3-211', number: 'Verso 211', text: `Tendo primeiro, de acordo com a regra, realizado, como um meio de proteger (o *Sraddha*), oblações a Agni, a Soma, e a Yama, que ele depois satisfaça os manes com um presente de comida sacrificial.` },
        { id: 'cm-3-212', number: 'Verso 212', text: `Mas se nenhum fogo (sagrado) (estiver disponível), ele deverá colocar (as oferendas) na mão de um *Brahmana*; pois *Brahmanas* que conhecem os textos sagrados declaram, 'O que o fogo é, assim é um *Brahmana*.'` },
        { id: 'cm-3-213', number: 'Verso 213', text: `Eles (também) chamam esses primeiros dos homens duas-vezes-nascidos as antigas deidades do sacrifício fúnebre, livres de ira, facilmente satisfeitos, empregados em fazer os homens prosperarem.` },
        { id: 'cm-3-214', number: 'Verso 214', text: `Após ele ter realizado (as oblações) no fogo, (e) toda a série de cerimônias de tal maneira que elas terminem no sul, que ele borrife água com sua mão direita no local (onde os bolos devem ser colocados).` },
        { id: 'cm-3-215', number: 'Verso 215', text: `Mas tendo feito três bolos do restante daquela comida sacrificial, ele deve, concentrando sua mente e virando-se em direção ao sul, colocá-los na (grama *Kusa*) exatamente da mesma maneira na qual (ele derramou as libações de) água.` },
        { id: 'cm-3-216', number: 'Verso 216', text: `Tendo oferecido aqueles bolos de acordo com a regra (prescrita), sendo puro, que ele limpe a mesma mão com (as raízes de) aquelas lâminas de grama *Kusa* pelo bem dos (três ancestrais) que partilham das limpezas (*lepa*).` },
        { id: 'cm-3-217', number: 'Verso 217', text: `Tendo (a seguir) sorvido água, virado-se (em direção ao norte), e três vezes lentamente suprimido sua respiração, o (sacrificador) que conhece os textos sagrados deverá adorar (as deidades guardiãs d)as seis estações e os manes.` },
        { id: 'cm-3-218', number: 'Verso 218', text: `Que ele gentilmente derrame o restante da água perto dos bolos, e, com atenção fixa, cheire aqueles bolos, na ordem em que foram colocados (no chão).` },
        { id: 'cm-3-219', number: 'Verso 219', text: `Mas pegando sucessivamente porções muito pequenas dos bolos, ele deverá fazer aqueles *Brahmanas* sentados comê-las, de acordo com a regra, antes (do jantar deles).` },
        { id: 'cm-3-220', number: 'Verso 220', text: `Mas se o pai (do sacrificador) está vivo, ele deve oferecer (os bolos) a três (ancestrais) mais remotos; ou ele pode também alimentar seu pai no sacrifício fúnebre como (um dos) (convidados) *Brahmanas*.` },
        { id: 'cm-3-221', number: 'Verso 221', text: `Mas aquele cujo pai está morto, enquanto seu avô vive, deverá, após pronunciar o nome de seu pai, mencionar (o de) seu bisavô.` },
        { id: 'cm-3-222', number: 'Verso 222', text: `Manu declarou que ou o avô pode comer naquele *Sraddha* (como um convidado), ou (o neto) tendo recebido permissão, pode realizá-lo, como ele deseja.` },
        { id: 'cm-3-223', number: 'Verso 223', text: `Tendo derramado água misturada com gergelim, na qual uma lâmina de grama *Kusa* foi colocada, nas mãos dos (convidados), ele deverá dar (a cada um) aquela porção (mencionada acima) do bolo, dizendo, 'A esses, *Svadha*!'` },
        { id: 'cm-3-224', number: 'Verso 224', text: `Mas carregando (o vaso) cheio de comida com ambas as mãos, o próprio (sacrificador) deverá gentilmente colocá-lo diante dos *Brahmanas*, meditando sobre os manes.` },
        { id: 'cm-3-225', number: 'Verso 225', text: `Os malevolentes *Asuras* arrancam à força aquela comida que é trazida sem ser segurada com ambas as mãos.` },
        { id: 'cm-3-226', number: 'Verso 226', text: `Que ele, sendo puro e atento, cuidadosamente coloque no chão o tempero (para o arroz), como caldos e ervas de panela, leite doce e azedo, e mel,` },
        { id: 'cm-3-227', number: 'Verso 227', text: `(Bem como) vários (tipos de) comida dura que requerem mastigação, e de comida macia, raízes, frutas, carne saborosa, e bebidas fragrantes.` },
        { id: 'cm-3-228', number: 'Verso 228', text: `Tudo isso ele deverá apresentar (aos seus convidados), sendo puro e atento, convidando-os sucessivamente a partilhar de cada (prato), proclamando suas qualidades.` },
        { id: 'cm-3-229', number: 'Verso 229', text: `Que ele sob nenhuma circunstância deixe cair uma lágrima, fique zangado ou profira uma inverdade, nem que ele toque a comida com o pé nem a sacuda violentamente.` },
        { id: 'cm-3-230', number: 'Verso 230', text: `Uma lágrima envia a (comida) aos *Pretas*, a ira aos seus inimigos, uma falsidade aos cães, o contato com o pé dele aos *Rakshasas*, um tremor aos pecadores.` },
        { id: 'cm-3-231', number: 'Verso 231', text: `O que quer que possa agradar aos *Brahmanas*, que ele dê sem relutar; que ele dê charadas do Veda, pois isso é agradável aos manes.` },
        { id: 'cm-3-232', number: 'Verso 232', text: `Em um (sacrifício em honra) aos manes, ele deve deixar (seus convidados) ouvirem o Veda, os Institutos da lei sagrada, lendas, contos, *Puranas*, e *Khilas*.` },
        { id: 'cm-3-233', number: 'Verso 233', text: `Estando ele próprio deleitado, que ele dê deleite aos *Brahmanas*, faça com que partilhem gradual e lentamente (de cada prato), e repetidamente os convide (a comer) por (oferecer) a comida e (louvar) suas qualidades.` },
        { id: 'cm-3-234', number: 'Verso 234', text: `Que ele avidamente entretenha em um sacrifício fúnebre o filho de uma filha, embora ele seja um estudante, e que ele coloque um cobertor do Nepal no assento (de cada convidado), espalhando grãos de gergelim no chão.` },
        { id: 'cm-3-235', number: 'Verso 235', text: `Há três meios de santificação, (a serem usados) em um *Sraddha*, o filho de uma filha, um cobertor do Nepal, e grãos de gergelim; e eles recomendam três (outras coisas) para ele, limpeza, supressão da ira, e ausência de pressa.` },
        { id: 'cm-3-236', number: 'Verso 236', text: `Toda a comida deve estar muito quente, e os (convidados) deverão comer em silêncio; (mesmo que) perguntados pelo doador (da festa), os *Brahmanas* não deverão proclamar as qualidades da comida sacrificial.` },
        { id: 'cm-3-237', number: 'Verso 237', text: `Enquanto a comida permanece quente, enquanto eles comem em silêncio, enquanto as qualidades da comida não são proclamadas, por esse tempo os manes partilham (dela).` },
        { id: 'cm-3-238', number: 'Verso 238', text: `O que (um convidado) come, cobrindo sua cabeça, o que ele come com sua face voltada em direção ao sul, o que ele come com sandálias (nos pés), isso os *Rakshasas* consomem.` },
        { id: 'cm-3-239', number: 'Verso 239', text: `Um *Kandala*, um porco de vila, um galo, um cão, uma mulher menstruada, e um eunuco não devem olhar para os *Brahmanas* enquanto comem.` },
        { id: 'cm-3-240', number: 'Verso 240', text: `O que (qualquer um) destes vê em uma oblação queimada, em um presente (solene), em um jantar (dado aos *Brahmanas*), ou em qualquer rito em honra aos deuses e manes, isso não produz o resultado pretendido.` },
        { id: 'cm-3-241', number: 'Verso 241', text: `Um javali torna (o rito) inútil ao inalar o cheiro (das oferendas), um galo pelo ar de suas asas, um cão ao lançar seu olho (sobre elas), um homem de casta baixa ao tocar (nelas).` },
        { id: 'cm-3-242', number: 'Verso 242', text: `Se um homem coxo, um homem de um olho só, um deficiente em um membro, ou um com um membro redundante, for mesmo o servo do realizador (do *Sraddha*), ele deve ser removido daquele local (onde o *Sraddha* é realizado).` },
        { id: 'cm-3-243', number: 'Verso 243', text: `A um (*chefe de família*) *Brahmana*, ou a um asceta que vem por comida, ele pode, com a permissão de (seus) (convidados) *Brahmanas*, mostrar honra de acordo com sua capacidade.` },
        { id: 'cm-3-244', number: 'Verso 244', text: `Que ele misture todos os tipos de comida juntos, borrife-os com água e os coloque, espalhando-os (na grama *Kusa*), no chão diante de (seus convidados), quando eles tiverem terminado sua refeição.` },
        { id: 'cm-3-245', number: 'Verso 245', text: `O resto (nos pratos), e a porção espalhada na grama *Kusa*, serão a parte das (crianças) falecidas que não receberam o sacramento (da cremação) e daqueles que (injustamente) abandonaram esposas nobres.` },
        { id: 'cm-3-246', number: 'Verso 246', text: `Eles declaram os fragmentos que caíram no chão em um (*Sraddha*) aos manes, como sendo a parte de servos honestos e zelosos no dever.` },
        { id: 'cm-3-247', number: 'Verso 247', text: `Mas antes da realização do *Sapindikarana*, deve-se alimentar no sacrifício fúnebre em honra a um Ariano (recentemente) falecido (um *Brahmana*) sem (fazer uma oferenda) aos deuses, e dar apenas um bolo.` },
        { id: 'cm-3-248', number: 'Verso 248', text: `Mas após o *Sapindikarana* do (pai falecido) ter sido realizado de acordo com a lei sagrada, os filhos devem oferecer os bolos com aquelas cerimônias, (descritas acima).` },
        { id: 'cm-3-249', number: 'Verso 249', text: `O homem tolo que, após ter comido um (jantar de) *Sraddha*, dá as sobras a um *Sudra*, cai de cabeça no inferno *Kalasutra*.` },
        { id: 'cm-3-250', number: 'Verso 250', text: `Se o partícipe de um (jantar de) *Sraddha* entra no mesmo dia na cama de uma fêmea *Sudra*, os manes de seus (ancestrais) jazerão durante aquele mês no excremento dela.` },
        { id: 'cm-3-251', number: 'Verso 251', text: `Tendo dirigido a pergunta, 'Jantastes bem?' (aos seus convidados), que ele dê água para sorver àqueles que estão satisfeitos, e os dispense, depois de terem sorvido a água, (com as palavras) 'Descansai seja (aqui ou em casa)!'` },
        { id: 'cm-3-252', number: 'Verso 252', text: `Os (convidados) *Brahmanas* deverão então responder a ele, 'Que haja *Svadha*'; pois em todos os ritos em honra aos manes a palavra *Svadha* é a bênção mais alta.` },
        { id: 'cm-3-253', number: 'Verso 253', text: `A seguir, que ele informe (seus convidados) que terminaram sua refeição, da comida que resta; com a permissão dos *Brahmanas* que ele disponha (daquilo), conforme eles possam direcionar.` },
        { id: 'cm-3-254', number: 'Verso 254', text: `Em um (*Sraddha*) em honra aos manes deve-se usar (ao perguntar aos convidados se estão satisfeitos, a palavra) *svaditam*; em um *Goshthi-sraddha*, (a palavra) *susrutam*; em um *Vriddhi-sraddha*, (a palavra) *sampannam*; e em (um rito) em honra aos deuses, (a palavra) *rukitam*.` },
        { id: 'cm-3-255', number: 'Verso 255', text: `A tarde, a grama *Kusa*, o devido preparo da habitação, os grãos de gergelim, a liberalidade, o preparo cuidadoso da comida, e (a companhia de) *Brahmanas* distintos são as verdadeiras riquezas em todos os sacrifícios fúnebres.` },
        { id: 'cm-3-256', number: 'Verso 256', text: `Sabei que a grama *Kusa*, os (textos) purificatórios, a manhã, as iguarias sacrificiais de todos os tipos, e aqueles meios de purificação, mencionados acima, são bênçãos em um sacrifício aos deuses.` },
        { id: 'cm-3-257', number: 'Verso 257', text: `A comida ingerida por eremitas na floresta, o leite, o suco de *Soma*, a carne que não é preparada (com temperos), e o sal não preparado por arte, são chamados, por conta de sua natureza, comida sacrificial.` },
        { id: 'cm-3-258', number: 'Verso 258', text: `Tendo dispensado os *Brahmanas* (convidados), que ele, com a mente concentrada, silencioso e puro, olhe em direção ao sul e peça estas bênçãos aos manes:` },
        { id: 'cm-3-259', number: 'Verso 259', text: `'Que homens generosos abundem conosco! Que (nosso conhecimento dos) Vedas e (nossa) progênie aumentem! Que a fé não nos abandone! Que possamos ter muito a dar (aos necessitados)!'` },
        { id: 'cm-3-260', number: 'Verso 260', text: `Tendo assim oferecido (os bolos), que ele, após (a oração), faça com que uma vaca, um *Brahmana*, uma cabra, ou o fogo sagrado consuma aqueles bolos, ou que ele os jogue na água.` },
        { id: 'cm-3-261', number: 'Verso 261', text: `Alguns fazem a oferenda dos bolos após (o jantar); alguns fazem com que (eles) sejam comidos por pássaros ou os jogam no fogo ou na água.` },
        { id: 'cm-3-262', number: 'Verso 262', text: `A primeira esposa (do sacrificador), que é fiel e dedicada à adoração dos manes, pode comer o bolo bem do meio, (se ela for) desejosa de gerar um filho.` },
        { id: 'cm-3-263', number: 'Verso 263', text: `(Assim) ela dará à luz um filho que terá vida longa, será famoso, inteligente, rico, pai de numerosa descendência, dotado de (qualidade de) bondade, e justo.` },
        { id: 'cm-3-264', number: 'Verso 264', text: `Tendo lavado suas mãos e sorvido água, que ele prepare (comida) para seus parentes paternos e, após dá-la a eles com o devido respeito, que ele alimente seus parentes maternos também.` },
        { id: 'cm-3-265', number: 'Verso 265', text: `Mas os restos deverão ser deixados (onde estão) até que os *Brahmanas* tenham sido dispensados; depois ele deverá realizar a (diária) oferenda doméstica *Bali*; essa é uma (regra) estabelecida (da) lei sagrada.` },
        { id: 'cm-3-266', number: 'Verso 266', text: `Eu declararei agora integralmente que tipo de comida sacrificial, dada aos manes de acordo com a regra, servirá por um longo tempo ou para a eternidade.` },
        { id: 'cm-3-267', number: 'Verso 267', text: `Os ancestrais dos homens são satisfeitos por um mês com grãos de gergelim, arroz, cevada, feijões *masha*, água, raízes, e frutas, que foram dados de acordo com a regra prescrita,` },
        { id: 'cm-3-268', number: 'Verso 268', text: `Dois meses com peixe, três meses com a carne de gazelas, quatro com carneiro, e cinco de fato com a carne de pássaros,` },
        { id: 'cm-3-269', number: 'Verso 269', text: `Seis meses com a carne de cabritos, sete com a de cervos pintados, oito com a de antílope negro, mas nove com a do (cervo chamado) *Ruru*,` },
        { id: 'cm-3-270', number: 'Verso 270', text: `Dez meses eles são satisfeitos com a carne de javalis e búfalos, mas onze meses de fato com a de lebres e tartarugas,` },
        { id: 'cm-3-271', number: 'Verso 271', text: `Um ano com leite de vaca e arroz-doce; da carne de um bode branco de orelhas longas a satisfação deles dura doze anos.` },
        { id: 'cm-3-272', number: 'Verso 272', text: `O (vegetal chamado) *Kalasaka*, (o peixe chamado) *Mahasalka*, a carne de um rinoceronte e a de um bode vermelho, e todos os tipos de comida ingerida por eremitas na floresta servem por um tempo infinito.` },
        { id: 'cm-3-273', number: 'Verso 273', text: `Qualquer (comida), misturada com mel, que alguém dá no décimo terceiro dia lunar na estação chuvosa sob o asterismo de *Maghah*, isso também proporciona infindável (satisfação).` },
        { id: 'cm-3-274', number: 'Verso 274', text: `'Que tal homem (dizem os manes) nasça em nossa família que nos dê arroz-doce, com mel e manteiga clarificada, no décimo terceiro dia lunar (do mês de Bhadrapada) e (à tarde) quando a sombra de um elefante cai em direção ao leste.'` },
        { id: 'cm-3-275', number: 'Verso 275', text: `O que quer que (um homem), cheio de fé, devidamente dá de acordo com a regra prescrita, isso se torna no outro mundo uma perpétua e imperecível (gratificação) para os manes.` },
        { id: 'cm-3-276', number: 'Verso 276', text: `Os dias da metade escura do mês, começando com o décimo, mas excetuando o décimo quarto, são recomendados para um sacrifício fúnebre; (não é) assim (com) os outros.` },
        { id: 'cm-3-277', number: 'Verso 277', text: `Aquele que o realiza nos dias (lunares) pares e sob as constelações pares, ganha (a realização de) todos os seus desejos; aquele que honra os manes nos (dias lunares) ímpares e sob as (constelações) ímpares, obtém descendência distinta.` },
        { id: 'cm-3-278', number: 'Verso 278', text: `Assim como a segunda metade do mês é preferível à primeira metade, assim também a tarde é melhor para (a realização de) um sacrifício fúnebre do que a manhã.` },
        { id: 'cm-3-279', number: 'Verso 279', text: `Que ele, incansável, realize devidamente os (ritos) em honra aos manes de acordo com a regra prescrita, passando o cordão sagrado sobre o ombro direito, procedendo da esquerda para a direita (e) segurando grama *Kusa* em suas mãos, até o fim (da cerimônia).` },
        { id: 'cm-3-280', number: 'Verso 280', text: `Que ele não realize um sacrifício fúnebre à noite, porque a (noite) é declarada pertencer aos *Rakshasas*, nem no crepúsculo, nem quando o sol acaba de nascer.` },
        { id: 'cm-3-281', number: 'Verso 281', text: `Que ele ofereça aqui embaixo um sacrifício fúnebre, de acordo com a regra dada acima, (pelo menos) três vezes ao ano, no inverno, no verão, e na estação chuvosa, mas aquele que é incluído entre os cinco grandes sacrifícios, todos os dias.` },
        { id: 'cm-3-282', number: 'Verso 282', text: `A oblação queimada, oferecida em um sacrifício aos manes, não deve ser feita em um fogo comum; um *Brahmana* que mantém um fogo sagrado não (deverá realizar) um sacrifício fúnebre exceto no dia de lua nova.` },
        { id: 'cm-3-283', number: 'Verso 283', text: `Mesmo quando um *Brahmana*, após banhar-se, satisfaz os manes com água, ele obtém com isso a recompensa inteira pela realização do *Sraddha* (diário).` },
        { id: 'cm-3-284', number: 'Verso 284', text: `Eles chamam (os manes de) pais de *Vasus*, (os de) avós de *Rudras*, e (os de) bisavós de *Adityas*; assim (fala) o eterno Veda.` },
        { id: 'cm-3-285', number: 'Verso 285', text: `Que ele diariamente partilhe do *vighasa* e diariamente coma *amrita* (ambrosia); mas *vighasa* é o que resta da refeição (de convidados *Brahmanas*) e o restante de um sacrifício (é chamado) *amrita*.` },
        { id: 'cm-3-286', number: 'Verso 286', text: `Assim todas as ordenanças relativas aos cinco (grandes diários) sacrifícios foram declaradas a vós; ouvi agora a lei para a maneira de viver apropriada para os *Brahmanas*.` },
      ],
    },
  ],
};
